import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as s,e}from"./app-4490560f.js";const t={},o=e(`<h1 id="btop-现代化终端资源监控器-cpu-内存-网络-磁盘" tabindex="-1"><a class="header-anchor" href="#btop-现代化终端资源监控器-cpu-内存-网络-磁盘" aria-hidden="true">#</a> btop（现代化终端资源监控器（CPU/内存/网络/磁盘））</h1><blockquote><p>Homebrew 版本 1.4.5 ｜ 主页：见官方文档 ｜ 安装：<code>brew install btop</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>btop 是一款用 C++ 编写的现代化终端资源监控器，对标经典 htop，用实时曲线、柱状图和彩色界面直观展示 CPU、内存、网络和磁盘的使用情况。它解决了传统 top 命令信息冗长、不直观的问题，让你在一个界面里就能看清整台机器的运行状态，特别适合服务器运维、性能排查和日常压测时观察资源占用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> btop

<span class="token comment"># 升级（先更新 Homebrew 索引）</span>
brew update <span class="token operator">&amp;&amp;</span> brew upgrade btop

<span class="token comment"># 卸载</span>
brew uninstall btop

<span class="token comment"># 验证安装成功（查看版本号）</span>
btop <span class="token parameter variable">--version</span>
<span class="token comment"># 输出示例：btop v1.4.5</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装完成后直接输入 <code>btop</code> 即可进入实时监控界面，按 <code>q</code> 或 <code>Esc</code> 退出。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><p>btop 主要通过交互式界面内的按键操作，也有少量命令行参数：</p><table><thead><tr><th>命令 / 按键</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>btop</code></td><td>启动监控界面</td><td><code>btop</code></td></tr><tr><td><code>btop -p 1,2,3</code></td><td>指定预设布局（1/2/3），显示不同模块组合</td><td><code>btop -p 1</code></td></tr><tr><td><code>btop -t</code></td><td>启用强制 256 色模式（配合终端的真彩模式）</td><td><code>btop -t</code></td></tr><tr><td><code>btop -v</code></td><td>输出版本号</td><td><code>btop -v</code></td></tr><tr><td><code>-r &lt;ms&gt;</code></td><td>设置刷新间隔（毫秒，默认 1500）</td><td><code>btop -r 500</code></td></tr><tr><td><code>-d</code></td><td>直接显示磁盘 IO 模块</td><td><code>btop -d</code></td></tr><tr><td><code>--utf-force</code></td><td>强制 UTF-8 模式（处理特殊字符乱码）</td><td><code>btop --utf-force</code></td></tr><tr><td><code>--low-color</code></td><td>使用低颜色方案，减少终端性能负担</td><td><code>btop --low-color</code></td></tr><tr><td><code>--update 1</code></td><td>设置刷新间隔为 1 秒（等价于 <code>-r 1000</code>）</td><td><code>btop --update 1</code></td></tr><tr><td><code>m</code></td><td>切换内存 / 交换分区显示</td><td><code>btop</code> 内按 <code>m</code></td></tr><tr><td><code>n</code></td><td>切换网络总览 / 进程显示</td><td><code>btop</code> 内按 <code>n</code></td></tr><tr><td><code>d</code></td><td>切换磁盘总览 / 分区 IO 显示</td><td><code>btop</code> 内按 <code>d</code></td></tr><tr><td><code>p</code></td><td>在预设布局间循环切换</td><td><code>btop</code> 内按 <code>p</code></td></tr><tr><td><code>?</code> 或 <code>h</code></td><td>打开按键帮助</td><td><code>btop</code> 内按 <code>?</code></td></tr><tr><td><code>f</code></td><td>按关键字过滤进程（支持正则）</td><td><code>btop</code> 内按 <code>f</code></td></tr><tr><td><code>t</code></td><td>切换进程树 / 列表视图</td><td><code>btop</code> 内按 <code>t</code></td></tr><tr><td><code>c</code></td><td>切换进程排序方式（树状时）</td><td><code>btop</code> 内按 <code>c</code></td></tr><tr><td><code>+</code> / <code>-</code></td><td>展开 / 折叠进程树节点</td><td><code>btop</code> 内按 <code>+</code> / <code>-</code></td></tr><tr><td><code>k</code></td><td>向选中进程发送信号（默认 SIGTERM）</td><td><code>btop</code> 内按 <code>k</code></td></tr><tr><td><code>e</code></td><td>查看进程的环境变量</td><td><code>btop</code> 内按 <code>e</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-启动并查看整体资源占用" tabindex="-1"><a class="header-anchor" href="#示例-1-启动并查看整体资源占用" aria-hidden="true">#</a> 示例 1：启动并查看整体资源占用</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接进入默认监控界面</span>
btop
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>界面顶部是 CPU 和内存曲线，中部是进程列表（按 CPU 占用排序）。观察要点：</p><ul><li>数字块颜色：绿色表示负载低，黄色表示中，红色表示高。</li><li>按 <code>↑</code>/<code>↓</code> 在进程间移动，按 <code>Enter</code> 或 <code>o</code> 查看该进程的详细信息（PID、线程、打开的文件等）。</li><li>按 <code>k</code> 直接结束选中的进程（会先要求确认）。</li></ul><h3 id="示例-2-快速定位高-cpu-进程并排序" tabindex="-1"><a class="header-anchor" href="#示例-2-快速定位高-cpu-进程并排序" aria-hidden="true">#</a> 示例 2：快速定位高 CPU 进程并排序</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 以 500ms 刷新、第一套布局启动，便于观察瞬时峰值</span>
btop <span class="token parameter variable">-r</span> <span class="token number">500</span> <span class="token parameter variable">-p</span> <span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>进入界面后，在进程区反复按 <code>P</code>（大写，CPU 排序）可以切换排序方向，找出占用最高的进程；按 <code>M</code> 按内存排序，排查内存泄漏。定位到可疑进程后按 <code>Enter</code> 查看其 PID，再配合 <code>kill &lt;PID&gt;</code> 在另一个终端里处理。</p><h3 id="示例-3-监控网络流量与磁盘-io" tabindex="-1"><a class="header-anchor" href="#示例-3-监控网络流量与磁盘-io" aria-hidden="true">#</a> 示例 3：监控网络流量与磁盘 IO</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接打开网络模块</span>
btop <span class="token parameter variable">-d</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>在界面内按 <code>n</code> 循环切换网络总览和网络进程视图，查看实时上传 / 下载速率（默认单位 bytes，可在设置中改成 bits）。按 <code>↑</code>/<code>↓</code> 或鼠标滚轮选择某个网卡，下方曲线会显示该网卡的实时吞吐。磁盘模块同理，能看到各分区读写速度和 IO 等待时间。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-配置文件与目录结构" tabindex="-1"><a class="header-anchor" href="#_1-配置文件与目录结构" aria-hidden="true">#</a> 1. 配置文件与目录结构</h3><p>btop 的配置文件位于 <code>~/.config/btop/</code>，首次运行后自动生成。目录结构如下：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>~/.config/btop/
├── btop.conf          <span class="token comment"># 主配置文件</span>
├── themes/            <span class="token comment"># 自定义主题目录（可选）</span>
│   └── mytheme.theme
└── btop.log           <span class="token comment"># 日志文件（出错时排查用）</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用编辑器打开配置</span>
<span class="token function">vim</span> ~/.config/btop/btop.conf
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>修改配置后，不需要重启 btop，直接在界面内按 <code>Esc</code> 打开主菜单 → <code>Options</code> → <code>Reload config</code>（或直接按 <code>r</code>）即可热重载，非常方便。</p><h3 id="_2-完整配置项逐条说明" tabindex="-1"><a class="header-anchor" href="#_2-完整配置项逐条说明" aria-hidden="true">#</a> 2. 完整配置项逐条说明</h3><p><code>btop.conf</code> 是 INI 风格，<code>#</code> 开头为注释。以下是一个经过整理、可直接使用的配置示例：</p><div class="language-ini line-numbers-mode" data-ext="ini"><pre class="language-ini"><code><span class="token comment"># ==== 主题与颜色 ====</span>
<span class="token key attr-name">color_theme</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;dracula&quot;          # 内置主题：default/dracula/monokai/nord/palenight/onedark/tokyo-night/ttcn 等</span>
<span class="token key attr-name">theme_background</span> <span class="token punctuation">=</span> <span class="token value attr-value">false         # 主题是否带背景色，true 时背景参与主题配色</span>
<span class="token key attr-name">truecolor</span> <span class="token punctuation">=</span> <span class="token value attr-value">true                 # 是否使用真彩（24-bit），旧终端可关掉</span>
<span class="token key attr-name">force_256</span> <span class="token punctuation">=</span> <span class="token value attr-value">false                # 强制 256 色（终端不支持真彩时开）</span>

<span class="token comment"># ==== 刷新与界面 ====</span>
<span class="token key attr-name">update_ms</span> <span class="token punctuation">=</span> <span class="token value attr-value">1500                 # 刷新间隔（毫秒），与 -r 参数等价</span>
<span class="token key attr-name">lowcolor</span> <span class="token punctuation">=</span> <span class="token value attr-value">false                 # 低颜色方案，终端卡顿时可开</span>
<span class="token key attr-name">tty_theme</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;default&quot;            # TTY 下使用的主题</span>
<span class="token key attr-name">graph_symbol</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;braille&quot;         # 曲线字符集：braille / block / tty / half</span>
<span class="token key attr-name">graph_symbol</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;block&quot;           # 后写覆盖前写，最终以 block 为准（曲线更醒目）</span>

<span class="token comment"># ==== 显示模块（控制首屏显示哪些面板） ====</span>
<span class="token key attr-name">shown_boxes</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;cpu mem net proc&quot; # 空格分隔，可选：cpu/mem/net/proc/disk</span>
<span class="token comment"># 顺序即显示顺序，例如想看磁盘和进程：shown_boxes = &quot;proc cpu disk&quot;</span>

<span class="token comment"># ==== CPU ====</span>
<span class="token key attr-name">cpu_graph_upper</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;total&quot;        # 顶部曲线：total（总览）/ per_core（每核）/ single（单核）</span>
<span class="token key attr-name">cpu_graph_lower</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;total&quot;        # 底部曲线</span>
<span class="token key attr-name">cpu_bottom_left</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;cpu&quot;          # 左下：cpu/disk/net/auto</span>
<span class="token key attr-name">cpu_bottom_right</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;mem&quot;         # 右下：cpu/disk/net/auto</span>

<span class="token comment"># ==== 内存 ====</span>
<span class="token key attr-name">mem_graph_upper</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;system&quot;       # system / used / free / hard</span>
<span class="token key attr-name">mem_graph_lower</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">system</span>&quot;</span>
<span class="token key attr-name">mem_bottom_left</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;mem&quot;          # mem / swap</span>
<span class="token key attr-name">mem_bottom_right</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">swap</span>&quot;</span>

<span class="token comment"># ==== 网络 ====</span>
<span class="token key attr-name">net_download</span> <span class="token punctuation">=</span> <span class="token value attr-value">100               # 下载速度图例上限（Mebibyte/s）</span>
<span class="token key attr-name">net_upload</span> <span class="token punctuation">=</span> <span class="token value attr-value">100                 # 上传速度图例上限</span>
<span class="token key attr-name">net_auto</span> <span class="token punctuation">=</span> <span class="token value attr-value">true                  # 自动调整速度上限</span>
<span class="token key attr-name">net_sync</span> <span class="token punctuation">=</span> <span class="token value attr-value">false                 # 上下行曲线同步</span>
<span class="token key attr-name">net_iface</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;&quot;                   # 默认监控网卡，留空自动探测</span>

<span class="token comment"># ==== 磁盘 ====</span>
<span class="token key attr-name">disk_show_io</span> <span class="token punctuation">=</span> <span class="token value attr-value">true              # 是否显示 IO 活动</span>
<span class="token key attr-name">disk_io_speeds</span> <span class="token punctuation">=</span> <span class="token value attr-value">true            # 是否显示 IO 速度</span>
<span class="token key attr-name">disk_free_priv</span> <span class="token punctuation">=</span> <span class="token value attr-value">false           # 只有 root 能查看分区详细信息</span>

<span class="token comment"># ==== 进程 ====</span>
<span class="token key attr-name">proc_sorting</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;cpu&quot;             # 默认排序：cpu / mem / pid / name</span>
<span class="token key attr-name">proc_reversed</span> <span class="token punctuation">=</span> <span class="token value attr-value">true             # 是否降序（true 从大到小）</span>
<span class="token key attr-name">proc_tree</span> <span class="token punctuation">=</span> <span class="token value attr-value">false                # 默认是否树状显示</span>
<span class="token key attr-name">proc_filter</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;&quot;                 # 默认过滤关键字（可留空）</span>
<span class="token key attr-name">proc_granularity</span> <span class="token punctuation">=</span> <span class="token value attr-value">true          # 进程占用精度（true 时计入所有线程）</span>
<span class="token key attr-name">proc_per_core</span> <span class="token punctuation">=</span> <span class="token value attr-value">false            # 是否按每核 CPU 占用显示</span>
<span class="token key attr-name">proc_mem_bytes</span> <span class="token punctuation">=</span> <span class="token value attr-value">true            # 内存列是否以字节精确显示</span>
<span class="token key attr-name">show_uptime</span> <span class="token punctuation">=</span> <span class="token value attr-value">true               # 是否显示开机时长</span>
<span class="token key attr-name">show_process</span> <span class="token punctuation">=</span> <span class="token value attr-value">true              # 是否显示进程列表</span>
<span class="token key attr-name">check_temp</span> <span class="token punctuation">=</span> <span class="token value attr-value">true                # 是否检测温度（需硬件支持）</span>
<span class="token key attr-name">temp_scale</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;celsius&quot;           # 温度单位：celsius / fahrenheit / kelvin</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-主题定制" tabindex="-1"><a class="header-anchor" href="#_3-主题定制" aria-hidden="true">#</a> 3. 主题定制</h3><p>btop 主题是简单的 <code>.theme</code> 文件，放在 <code>~/.config/btop/themes/</code> 下，重启后在 <code>Options → Color theme</code> 里就能看到。以下是一个自定义主题的最小骨架：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 创建一个极简主题文件</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> ~/.config/btop/themes
<span class="token function">cat</span> <span class="token operator">&gt;</span> ~/.config/btop/themes/ocean.theme <span class="token operator">&lt;&lt;</span> <span class="token string">&#39;EOF&#39;
[color]
main = &quot;\\e[38;2;97;175;239m&quot;
proc_cpu = &quot;\\e[38;2;255;255;255m&quot;
proc_mem = &quot;\\e[38;2;142;188;255m&quot;
proc_misc = &quot;\\e[38;2;135;150;200m&quot;
cpu_core = &quot;\\e[38;2;86;156;214m&quot;
cpu_user = &quot;\\e[38;2;97;175;239m&quot;
cpu_system = &quot;\\e[38;2;198;120;221m&quot;
cpu_nice = &quot;\\e[38;2;142;188;255m&quot;
mem_used = &quot;\\e[38;2;255;200;87m&quot;
mem_cached = &quot;\\e[38;2;97;175;239m&quot;
mem_free = &quot;\\e[38;2;46;160;67m&quot;
EOF</span>
<span class="token comment"># 然后启动 btop，在 Options → Color theme 里选择 ocean</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-环境变量" tabindex="-1"><a class="header-anchor" href="#_4-环境变量" aria-hidden="true">#</a> 4. 环境变量</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 让 btop 使用真彩（24-bit）配色（推荐，界面更鲜艳）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">COLORTERM</span></span><span class="token operator">=</span>truecolor

<span class="token comment"># 强制 256 色（真彩发灰或乱码时）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">COLORTERM</span></span><span class="token operator">=</span><span class="token number">1</span>

<span class="token comment"># 让 btop 跟随系统深浅色主题（需终端与桌面环境支持）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">BTOP_DARK_BG</span><span class="token operator">=</span><span class="token number">1</span>

<span class="token comment"># 覆盖配置文件路径（自定义配置目录时很有用）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">BTOP_CONFIG_DIR</span><span class="token operator">=</span><span class="token string">&quot;<span class="token environment constant">$HOME</span>/.config/btop_alt&quot;</span>
btop   <span class="token comment"># 此时会读取新目录下的配置</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-命令行进阶参数" tabindex="-1"><a class="header-anchor" href="#_5-命令行进阶参数" aria-hidden="true">#</a> 5. 命令行进阶参数</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用环境变量关闭颜色，方便无颜色日志导出</span>
btop <span class="token parameter variable">-t</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null   <span class="token comment"># -t 为 256 色；输出到管道时建议配合 --low-color</span>

<span class="token comment"># 组合参数：500ms 刷新 + 仅显示 CPU 和内存模块 + 强 256 色</span>
btop <span class="token parameter variable">-r</span> <span class="token number">500</span> <span class="token parameter variable">-p</span> cpu,mem <span class="token parameter variable">-t</span>

<span class="token comment"># 查看完整命令行帮助</span>
btop <span class="token parameter variable">--help</span>
<span class="token comment"># 输出示例：</span>
<span class="token comment">#   Usage: btop [OPTIONS]</span>
<span class="token comment">#   -h, --help        Print this help message and exit</span>
<span class="token comment">#   -v, --version     Print version information and exit</span>
<span class="token comment">#   -l, --low-color   Disable truecolor theme</span>
<span class="token comment">#   -t, --force-256   Force 256 color even if truecolor is detected</span>
<span class="token comment">#   --utf-force        Force start even if no UTF-8 locale is detected</span>
<span class="token comment">#   --update &lt;ms&gt;     Set the update rate in milliseconds</span>
<span class="token comment">#   --threads         Show threads and process groups</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-完整监控面板逐模块解读" tabindex="-1"><a class="header-anchor" href="#_6-完整监控面板逐模块解读" aria-hidden="true">#</a> 6. 完整监控面板逐模块解读</h3><p>btop 的&quot;面板&quot;用 <code>shown_boxes</code> 控制，每个模块都有独立的数据语义。读懂这些模块 = 读懂一台机器的健康度：</p><p><strong>CPU 面板</strong></p><ul><li>顶部大曲线默认 <code>cpu_graph_upper = &quot;total&quot;</code>：显示全部核心的<strong>总和占用</strong>随时间变化；切到 <code>per_core</code> 则显示每个核心各自的曲线堆叠（可看清是否&quot;单核打满、多核空闲&quot;——常见于单线程程序瓶颈）。</li><li>左下/右下小图是&quot;当前核心&quot;的细分：<code>cpu_user</code>（用户态）、<code>cpu_system</code>（内核态）、<code>cpu_nice</code>（低优先级）、<code>cpu_io</code>（等待 IO）。若 <code>system</code> 常年高，说明有系统调用/内核工作瓶颈（如频繁中断、磁盘 IO 等待）。</li></ul><p><strong>内存面板</strong></p><ul><li><code>mem_graph_upper = &quot;system&quot;</code>：系统总内存的构成堆叠。把鼠标移到图上看图例：<code>used</code>（已用）、<code>cached</code>（缓存，可回收）、<code>free</code>（空闲）。</li><li><strong>判断真实压力的关键</strong>：<code>used + cached + free</code> 才是&quot;物理总量&quot;，<code>cached</code> 是系统为加速读取临时占用的、<strong>可以释放</strong>的，所以&quot;used&quot;高不一定内存紧张，要看 <code>free + cached</code> 是否长期逼近 0，以及 swap 是否开始被频繁读写。</li></ul><p><strong>网络面板</strong></p><ul><li>两张曲线分别画**下行（下载）<strong>与</strong>上行（上传）**速率，<code>net_download</code>/<code>net_upload</code> 决定图例纵轴上限，<code>net_auto = true</code> 时自动缩放。</li><li>数字区域给出当前瞬时速率，<code>net_iface</code> 可固定要监控的网卡（多网卡/服务器场景很关键，否则自动探测可能抓到错误的回环接口）。</li><li>按 <code>n</code> 切换到&quot;网络进程&quot;视图，可看<strong>哪个进程正在占带宽</strong>——排查&quot;谁在偷偷上传/下载&quot;的利器。</li></ul><p><strong>磁盘面板</strong></p><ul><li>上方是各分区读/写速率曲线，<code>disk_show_io</code> 控制是否显示 IO 等待时间（<code>iowait</code>）。<strong>iowait 高</strong>意味着磁盘成为瓶颈（CPU 在干等磁盘），即使 CPU 占用不高，整机也慢。</li><li>按 <code>d</code> 切换到&quot;分区总览&quot;视图看容量与挂载点，配合 <code>ncdu</code> 定位谁占空间。</li></ul><p><strong>进程面板</strong></p><ul><li>排序：<code>P</code>（CPU）、<code>M</code>（内存）、<code>T</code>（累计 CPU 时间）、<code>N</code>（PID）、<code>I</code>（进程名）。<code>proc_sorting</code> 设置默认排序。</li><li><code>proc_granularity</code>：默认 <code>true</code> 会把进程的所有线程占用都<strong>合计</strong>进该进程，避免&quot;每个线程只有 0.x%，看不出来谁在忙&quot;的盲区。</li><li><code>proc_tree</code> / 按 <code>t</code>：树形视图展示父子关系，按 <code>c</code> 切换排序，按 <code>+</code>/<code>-</code> 折叠节点。</li><li><code>proc_per_core = true</code> 时，CPU 列显示的是&quot;占了多少个核心&quot;，大于 1 说明该进程是多线程并行。</li></ul><h3 id="_7-脚本模式与「纯文本」输出" tabindex="-1"><a class="header-anchor" href="#_7-脚本模式与「纯文本」输出" aria-hidden="true">#</a> 7. 脚本模式与「纯文本」输出</h3><p>btop 本身是 TUI，不直接输出可解析文本。但有两个脚本友好的方向：</p><p><strong>① 用 <code>btop</code> 做&quot;人工决策 + 脚本执行&quot;</strong><br> btop 只负责&quot;人眼观察&quot;，真正要交给 cron/CI 的数据采集一律走 <code>ps</code> / <code>top -b</code> / <code>sysctl</code> / <code>vm_stat</code>（见第七节），这是脚本化的正确姿势。</p><p><strong>② 结合 <code>tmux</code> / <code>script</code> 把 TUI 输出落档</strong><br> 若确需把 btop 的实时画面保存为文本，可用 <code>tmux</code> 捕获窗格内容，或 <code>script</code> 记录会话：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用 script 记录整段 btop 会话到文件（之后可 cat 查看）</span>
script /tmp/btop_session.log
btop
<span class="token builtin class-name">exit</span>

<span class="token comment"># 或用 tmux 窗格捕获</span>
tmux new <span class="token parameter variable">-d</span> <span class="token parameter variable">-s</span> cap <span class="token string">&#39;btop -r 2000&#39;</span>
<span class="token function">sleep</span> <span class="token number">3</span>
tmux capture-pane <span class="token parameter variable">-t</span> cap <span class="token parameter variable">-p</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-40</span>   <span class="token comment"># 抓当前画面文本</span>
tmux kill-session <span class="token parameter variable">-t</span> cap
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-与其它工具搭配" tabindex="-1"><a class="header-anchor" href="#_8-与其它工具搭配" aria-hidden="true">#</a> 8. 与其它工具搭配</h3><ul><li>用 <code>watch -n 1 btop -r 1000</code> 以固定节奏刷新观察；</li><li>结合 <code>htop</code> / <code>top</code> 做交叉对比；</li><li>配合 SSH 远程登录服务器后运行，实时查看远端机器负载（注意网络延迟，可把刷新间隔调大，如 <code>btop -r 3000</code>）。</li></ul><h3 id="_9-预设布局与个性化" tabindex="-1"><a class="header-anchor" href="#_9-预设布局与个性化" aria-hidden="true">#</a> 9. 预设布局与个性化</h3><p>btop 内置 3 套预设布局（<code>-p 1/2/3</code>），也可以通过配置 <code>shown_boxes</code> 组合出属于自己的布局。实际调法：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只保留 CPU + 网络（做网络压测观察时，省掉进程/磁盘噪声）</span>
btop <span class="token parameter variable">-p</span> cpu,net

<span class="token comment"># 只保留内存 + 进程（查内存泄漏时聚焦）</span>
btop <span class="token parameter variable">-p</span> mem,proc

<span class="token comment"># 想看全：磁盘 + CPU + 网络 + 内存 + 进程</span>
btop <span class="token parameter variable">-p</span> cpu,mem,net,proc,disk
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>把最常用的那套写进 <code>btop.conf</code> 的 <code>shown_boxes</code>，开机即用，免去每次手动切换。</p><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-终端兼容性" tabindex="-1"><a class="header-anchor" href="#_1-终端兼容性" aria-hidden="true">#</a> 1. 终端兼容性</h3><p>btop 需要较新的终端（如 iTerm2、kitty、Windows Terminal、支持真彩的 xterm），老终端可能出现乱码或颜色异常。遇到花屏先尝试 <code>btop -t</code>，或升级终端。若字符显示为方块乱码，可能是终端未启用 UTF-8 编码，可用 <code>btop --utf-force</code> 强制启动。</p><h3 id="_2-按键与中文输入法冲突" tabindex="-1"><a class="header-anchor" href="#_2-按键与中文输入法冲突" aria-hidden="true">#</a> 2. 按键与中文输入法冲突</h3><p>在中文输入法开启时，快捷键（如 <code>q</code>、<code>p</code>）可能无法触发。按 <code>Ctrl+Space</code> 或 <code>Ctrl+</code> 切换到英文输入法再操作。</p><h3 id="_3-进程列表为空或乱序" tabindex="-1"><a class="header-anchor" href="#_3-进程列表为空或乱序" aria-hidden="true">#</a> 3. 进程列表为空或乱序</h3><p>macOS 上若权限不足，部分进程信息可能不完整。建议通过 sudo 或确保当前用户权限正常；磁盘模块在某些容器 / 虚拟化环境可能显示不出 IO。</p><h3 id="_4-刷新太频繁导致高-cpu-占用" tabindex="-1"><a class="header-anchor" href="#_4-刷新太频繁导致高-cpu-占用" aria-hidden="true">#</a> 4. 刷新太频繁导致高 CPU 占用</h3><p><code>-r</code> 设太小的值（如 200ms）会让 btop 自身消耗较多资源，干扰观察结果。日常用默认 1500ms 即可，排查瞬时峰值再临时调小。</p><h3 id="_5-退出方式" tabindex="-1"><a class="header-anchor" href="#_5-退出方式" aria-hidden="true">#</a> 5. 退出方式</h3><p>直接按 <code>q</code> 或 <code>Esc</code> 退出；若界面卡住，可先按 <code>Ctrl+C</code> 再按 <code>q</code> 兜底，正常不会留下残留进程。</p><h3 id="_6-常见报错与解决办法" tabindex="-1"><a class="header-anchor" href="#_6-常见报错与解决办法" aria-hidden="true">#</a> 6. 常见报错与解决办法</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 报错：Fatal error: Could not find a usable terminal</span>
<span class="token comment"># 原因：终端环境变量 TERM 缺失或异常</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable"><span class="token environment constant">TERM</span></span><span class="token operator">=</span>xterm-256color <span class="token operator">&amp;&amp;</span> btop

<span class="token comment"># 报错：Unsupported terminal. Setting TERM to xterm or installing a newer</span>
<span class="token comment">#       terminal emulator is recommended.</span>
<span class="token comment"># 原因：终端不支持所需特性，用 -t 强制 256 色，或升级终端</span>
btop <span class="token parameter variable">-t</span>

<span class="token comment"># 报错：No UTF-8 locale detected</span>
<span class="token comment"># 原因：系统语言环境非 UTF-8，用 --utf-force 强制，或修正 locale</span>
btop --utf-force
<span class="token comment"># 永久修复：export LANG=en_US.UTF-8 LC_ALL=en_US.UTF-8</span>

<span class="token comment"># 界面全是方块、曲线缺失</span>
<span class="token comment"># 原因：graph_symbol 字符集不被终端支持，改用 block 或 lowcolor</span>
btop --low-color
<span class="token comment"># 或改配置 graph_symbol = &quot;block&quot;</span>

<span class="token comment"># 温度模块不显示</span>
<span class="token comment"># 原因：硬件未暴露温度传感器或权限不足，可忽略 check_temp = false</span>

<span class="token comment"># 网络曲线始终是 0 或抓错网卡</span>
<span class="token comment"># 原因：net_iface 未固定或自动探测抓到了 lo 回环</span>
<span class="token comment"># 在配置里显式固定网卡，如 net_iface = &quot;en0&quot;（macOS）或 eth0（Linux）</span>

<span class="token comment"># 内存&quot;已用&quot;接近 100% 但系统不卡</span>
<span class="token comment"># 原因：cached 缓存被计入 used，并非真实内存压力</span>
<span class="token comment"># 看 free+cached 是否仍有余额，以及 swap 是否在涨；别被单一数字吓到</span>

<span class="token comment"># 磁盘 IO 显示不出来的场景</span>
<span class="token comment"># 原因：虚拟化/容器环境对 /proc/diskstats 或 sysctl 读取受限</span>
<span class="token comment"># 用 df -h 兜底看容量，IO 速率改用 iostat / sar 侧证</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-性能与安全注意点" tabindex="-1"><a class="header-anchor" href="#_7-性能与安全注意点" aria-hidden="true">#</a> 7. 性能与安全注意点</h3><ul><li><strong>避免在生产/线上机器长时间开着高频刷新</strong>：<code>btop -r 200</code> 会显著吃掉 CPU，若需长时间监控用默认间隔或 <code>btop --update 1</code>。</li><li><strong>不要用 <code>watch btop</code> 在无 tty 的 CI 或脚本里反复启动</strong>：btop 需要交互式终端（tty），在 <code>cron</code>、<code>nohup</code> 或管道重定向中会直接报 <code>Could not find a usable terminal</code>，此时应改用 <code>ps</code> / <code>top -b -n 1</code> 或 <code>sar</code>。</li><li><strong>进程信号发送要谨慎</strong>：按 <code>k</code> 结束进程时默认发 <code>SIGTERM</code>，确认 PID 无误再确认；误杀关键系统进程可能导致机器卡死。</li><li><strong>安全提示</strong>：在多人共享服务器上，<code>e</code> 查看进程环境变量可能泄露密钥等敏感信息，注意不要将包含凭据的进程信息截图外传。</li><li><strong>日志文件增长</strong>：若 btop 内部出错，<code>~/.config/btop/btop.log</code> 会持续写入，可定期清理或删除该目录。</li><li><strong>macOS 上温度/IO 读数可能缺失</strong>：Apple Silicon 的传感器接口与 Linux 不同，温度、某些磁盘 IO 指标读不到属正常，别误判为故障。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_1-一键监控脚本-含报警" tabindex="-1"><a class="header-anchor" href="#_1-一键监控脚本-含报警" aria-hidden="true">#</a> 1. 一键监控脚本（含报警）</h3><p>btop 本身无告警能力，但可配合 Shell 脚本 + <code>osascript</code>（macOS）或 <code>notify-send</code>（Linux）实现资源超限提醒：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/bin/bash</span>
<span class="token comment"># monitor.sh —— 一键启动带视觉提示的监控，资源超限时响铃提醒</span>
btop <span class="token parameter variable">-r</span> <span class="token number">1000</span> <span class="token operator">&amp;</span>
<span class="token assign-left variable">BTOP_PID</span><span class="token operator">=</span><span class="token variable">$!</span>
<span class="token comment"># 后台每秒检查一次 CPU 负载</span>
<span class="token keyword">while</span> <span class="token function">kill</span> <span class="token parameter variable">-0</span> <span class="token variable">$BTOP_PID</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null<span class="token punctuation">;</span> <span class="token keyword">do</span>
    <span class="token assign-left variable">load</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">sysctl</span> <span class="token parameter variable">-n</span> vm.loadavg <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span>   <span class="token comment"># macOS 负载均值</span>
    <span class="token keyword">if</span> <span class="token function">awk</span> <span class="token parameter variable">-v</span> <span class="token assign-left variable">l</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$load</span>&quot;</span> <span class="token string">&#39;BEGIN {exit !(l &gt; 2.0)}&#39;</span><span class="token punctuation">;</span> <span class="token keyword">then</span>
        <span class="token builtin class-name">echo</span> <span class="token string">&quot;⚠️ 负载过高: <span class="token variable">$load</span>&quot;</span>
        afplay /System/Library/Sounds/Sosumi.aiff <span class="token operator">&amp;</span>   <span class="token comment"># macOS 提示音</span>
        <span class="token function">sleep</span> <span class="token number">10</span>                                       <span class="token comment"># 冷却，避免刷屏</span>
    <span class="token keyword">fi</span>
    <span class="token function">sleep</span> <span class="token number">1</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">chmod</span> +x monitor.sh <span class="token operator">&amp;&amp;</span> ./monitor.sh
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_2-与-htop-top-交叉排查" tabindex="-1"><a class="header-anchor" href="#_2-与-htop-top-交叉排查" aria-hidden="true">#</a> 2. 与 <code>htop</code> / <code>top</code> 交叉排查</h3><p>btop 适合整体概览，<code>htop</code> 适合精细进程树，<code>top -b</code> 适合无交互输出。定位问题时按角色分工：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1) btop 快速看哪个模块异常（CPU/内存/磁盘）</span>
btop <span class="token parameter variable">-r</span> <span class="token number">500</span>

<span class="token comment"># 2) 切到 htop 按 F5 看进程树、F4 过滤定位嫌疑进程</span>
<span class="token function">htop</span>

<span class="token comment"># 3) 用 top 批处理模式导出快照用于分析（无 tty 也能跑）</span>
<span class="token function">top</span> <span class="token parameter variable">-b</span> <span class="token parameter variable">-n</span> <span class="token number">1</span> <span class="token parameter variable">-o</span> %CPU <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-30</span> <span class="token operator">&gt;</span> /tmp/cpu_snapshot.txt
<span class="token function">cat</span> /tmp/cpu_snapshot.txt
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-批量采集与巡检-配合-cron" tabindex="-1"><a class="header-anchor" href="#_3-批量采集与巡检-配合-cron" aria-hidden="true">#</a> 3. 批量采集与巡检（配合 cron）</h3><p>btop 无法直接在脚本里输出数据，但可用它做人工巡检，数据采集交给 <code>top -b</code> 或 <code>sar</code>。下面演示把监控数据归档：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/bin/bash</span>
<span class="token comment"># snapshot.sh —— 定时抓取资源快照，供人工巡检</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> ~/monitor
<span class="token assign-left variable">ts</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d_%H%M%S<span class="token variable">)</span></span>
<span class="token comment"># 进程 TOP 数据（CPU/内存排序各一份）</span>
<span class="token function">top</span> <span class="token parameter variable">-b</span> <span class="token parameter variable">-n</span> <span class="token number">1</span> <span class="token parameter variable">-o</span> %CPU <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-25</span> <span class="token operator">&gt;</span> ~/monitor/top_cpu_<span class="token variable">$ts</span>.txt
<span class="token function">top</span> <span class="token parameter variable">-b</span> <span class="token parameter variable">-n</span> <span class="token number">1</span> <span class="token parameter variable">-o</span> %MEM <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-25</span> <span class="token operator">&gt;</span> ~/monitor/top_mem_<span class="token variable">$ts</span>.txt
<span class="token comment"># 磁盘空间</span>
<span class="token function">df</span> <span class="token parameter variable">-h</span> <span class="token operator">&gt;</span> ~/monitor/disk_<span class="token variable">$ts</span>.txt
<span class="token comment"># 保留最近 7 天，清理更旧的</span>
<span class="token function">find</span> ~/monitor <span class="token parameter variable">-name</span> <span class="token string">&#39;*.txt&#39;</span> <span class="token parameter variable">-mtime</span> +7 <span class="token parameter variable">-delete</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>crontab -e</code> 每 30 分钟执行一次：</p><div class="language-cron line-numbers-mode" data-ext="cron"><pre class="language-cron"><code>*/30 * * * * /Users/wangbo/monitor/snapshot.sh
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_4-ci-cd-集成-非交互环境" tabindex="-1"><a class="header-anchor" href="#_4-ci-cd-集成-非交互环境" aria-hidden="true">#</a> 4. CI / CD 集成（非交互环境）</h3><p>CI 是纯非交互环境，btop 会因无 tty 失败，此时<strong>不要用 btop</strong>，改用如下方案做资源门槛检查：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># GitHub Actions 示例：构建前检查可用内存（防止 OOM）</span>
<span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Check available memory
  <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
    mem=$(sysctl -n hw.memsize)   # macOS runner
    echo &quot;Total memory: $(( mem / 1024 / 1024 / 1024 )) GB&quot;
    free_mem=$(vm_stat | awk &#39;/free/ {print $3}&#39; | tr -d &#39;.&#39;)
    echo &quot;Free pages: $free_mem&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>或使用 <code>nproc</code>、<code>ulimit</code> 配合构建工具限制并发：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 限制构建并发以控制内存峰值（配合 btop 本地观察）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">MAKEFLAGS</span><span class="token operator">=</span><span class="token string">&quot;-j<span class="token variable"><span class="token variable">$(</span>nproc <span class="token parameter variable">--ignore</span><span class="token operator">=</span><span class="token number">1</span><span class="token variable">)</span></span>&quot;</span>
<span class="token comment"># 或显式降并发</span>
<span class="token function">make</span> <span class="token parameter variable">-j2</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-与-ncdu-du-结合排查磁盘" tabindex="-1"><a class="header-anchor" href="#_5-与-ncdu-du-结合排查磁盘" aria-hidden="true">#</a> 5. 与 <code>ncdu</code> / <code>du</code> 结合排查磁盘</h3><p>btop 磁盘模块只给速率和容量，不定位“谁占了空间”，配合 <code>ncdu</code> 快速定位大文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先看哪块盘满了</span>
btop <span class="token parameter variable">-d</span>
<span class="token comment"># 再定位大目录（交互式，方向键浏览）</span>
ncdu /path/to/disk
<span class="token comment"># 或命令行快速排序</span>
<span class="token function">du</span> <span class="token parameter variable">-ah</span> /path <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rh</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-20</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-与-lsof-netstat-结合排查进程与端口" tabindex="-1"><a class="header-anchor" href="#_6-与-lsof-netstat-结合排查进程与端口" aria-hidden="true">#</a> 6. 与 <code>lsof</code> / <code>netstat</code> 结合排查进程与端口</h3><p>btop 按 <code>Enter</code> 查看进程详细信息，若需知道进程占用了哪些端口/文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先记下可疑进程 PID</span>
<span class="token comment"># 查该 PID 打开的端口</span>
<span class="token function">lsof</span> <span class="token parameter variable">-i</span> <span class="token parameter variable">-P</span> <span class="token parameter variable">-n</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span>
<span class="token comment"># 查该 PID 打开的文件</span>
<span class="token function">lsof</span> <span class="token parameter variable">-p</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span>
<span class="token comment"># 网络连接状态统计</span>
<span class="token function">netstat</span> <span class="token parameter variable">-an</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $6}&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-makefile-一键化监控" tabindex="-1"><a class="header-anchor" href="#_7-makefile-一键化监控" aria-hidden="true">#</a> 7. Makefile 一键化监控</h3><p>把常用监控命令收进 Makefile，实现一键调用：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile —— make monitor 即可监控</span>
<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> monitor top net disk help

<span class="token target symbol">monitor</span><span class="token punctuation">:</span>          <span class="token comment">## 打开交互式 btop</span>
	<span class="token operator">@</span>btop -r 1000

<span class="token target symbol">top</span><span class="token punctuation">:</span>              <span class="token comment">## 输出 CPU 排序快照</span>
	<span class="token operator">@</span>top -b -n 1 -o %CPU <span class="token operator">|</span> head -30

<span class="token target symbol">net</span><span class="token punctuation">:</span>              <span class="token comment">## 显示网卡流量</span>
	<span class="token operator">@</span>ifstat -i en0 1 5

<span class="token target symbol">disk</span><span class="token punctuation">:</span>             <span class="token comment">## 显示磁盘占用</span>
	<span class="token operator">@</span>df -h

<span class="token target symbol">help</span><span class="token punctuation">:</span>             <span class="token comment">## 显示帮助</span>
	<span class="token operator">@</span>grep <span class="token string">&#39;^[a-zA-Z]&#39;</span> Makefile <span class="token operator">|</span> awk -F<span class="token string">&#39;:&#39;</span> <span class="token string">&#39;{print $$1}&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">make</span> <span class="token builtin class-name">help</span> <span class="token operator">&amp;&amp;</span> <span class="token function">make</span> monitor
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="_8-生产级实践清单" tabindex="-1"><a class="header-anchor" href="#_8-生产级实践清单" aria-hidden="true">#</a> 8. 生产级实践清单</h3><ul><li><strong>监控前先校准基线</strong>：在负载正常时跑一次 <code>btop</code> 截图记录各模块典型值，作为日后对比基准。</li><li><strong>区分“瞬时”与“持续”</strong>：用 <code>btop -r 500</code> 抓瞬时峰值，再用 <code>top -b -n 60 | tail</code> 或 <code>sar</code> 看持续趋势，避免被单次毛刺误导。</li><li><strong>善用进程树与线程</strong>：按 <code>t</code> 切到树状视图、配合 <code>e</code> 查看环境变量，能快速发现“僵尸进程”或异常多线程进程。</li><li><strong>远程排查注意延迟</strong>：SSH 高延迟时把 <code>update_ms</code> 调大到 3000 以上，否则界面会严重卡顿且刷新失真。</li><li><strong>把 btop 当作“入口”，把 <code>ps/lsof/ncdu/sar</code> 当作“手术刀”</strong>：btop 负责快速定位问题模块，专业工具负责深挖细节，两者配合效率最高。</li><li><strong>固定配置文件</strong>：把调好的 <code>~/.config/btop/btop.conf</code> 和自定义主题纳入 dotfiles 版本管理，多台机器一键同步，监控界面全局一致。</li></ul>`,105),c=[o];function l(i,d){return a(),s("div",null,c)}const u=n(t,[["render",l],["__file","btop.html.vue"]]);export{u as default};
